function updateAtlasLock(){const button=$('[data-atlas-follow]');if(button)button.hidden=!atlasLocked;if(atlasLocked&&$('#atlasPhaseLabel'))$('#atlasPhaseLabel').textContent='已选中 · '+atlasName(atlasItems.find(i=>i.key===mapSelected)||atlasItems[0]);}
function applyAtlasSelection(){updateAtlasLock();$$('[data-map-row]').forEach(e=>{const on=e.dataset.mapRow===mapSelected;e.classList.toggle('selected',on);if(on)e.setAttribute('aria-current','location');else e.removeAttribute('aria-current');e.querySelector('.ia-list-number')?.setAttribute('aria-pressed',String(on));});$$('[data-atlas-marker]').forEach(e=>{const on=e.dataset.atlasMarker===mapSelected;e.classList.toggle('selected',on);e.setAttribute('aria-pressed',String(on));});}
function selectMapPlace(key,scroll=true,step,automatic=false){key=atlasKey(key);const item=atlasItems.find(i=>i.key===key);if(!item)return;if(!automatic)atlasLocked=true;if(step!==undefined&&Number.isInteger(+step)&&+step>=0&&+step<selectedPlan(DATA.days[item.day-1]).length){atlasFocusSteps.set(mapFilter+':'+key,{step:+step,phase:atlasPhase});const row=$$('[data-map-row]').find(e=>e.dataset.mapRow===key);if(row)row.querySelector('[data-day]').dataset.focusStep=String(step);}mapSelected=key;const desired=atlasTarget(item),button=$$('[data-atlas-open]').find(b=>b.dataset.atlasOpen===key);if(button&&desired.step!==undefined)button.dataset.focusStep=String(desired.step);if(atlasConfig?.id==='world'||atlasConfig?.id==='overview')layoutAtlas();else applyAtlasSelection();saveMapContext();if(scroll){const row=$$('[data-map-row]').find(e=>e.dataset.mapRow===key),panel=$('.ia-scroll');if(row&&panel){const r=row.getBoundingClientRect(),b=panel.getBoundingClientRect();if(r.top<b.top||r.bottom>b.bottom)panel.scrollTo({top:panel.scrollTop+r.top-b.top-6,behavior:reduced()?'instant':'smooth'});}}}
function selectMapVisit(id){selectMapPlace(id);}
function fitMap(){} // Historical delegated action only; no fit control is rendered.
async function atlasCacheStatus(){const el=$('#atlasSaved'),config=atlasConfig;if(!el||!config)return;try{const cache=await caches.open('nordic-map-illustrated-v1'),url=new URL('maps/illustrated-v1/'+config.file,document.baseURI),hit=await cache.match(url);if(el.isConnected&&atlasConfig===config)el.textContent=hit?'当前区域插画已保存':'尚未核验当前区域离线地图';}catch{if(el.isConnected)el.textContent='此浏览器不能保存离线地图';}}
async function prepareAtlasMap(){const button=$('[data-atlas-save]'),el=$('#atlasSaved'),config=atlasConfig;if(!button||button.disabled)return;button.disabled=true;el.textContent='正在保存…';try{if(!('caches'in window))throw Error('此浏览器不支持地图缓存');const cache=await caches.open('nordic-map-illustrated-v1'),url=new URL('maps/illustrated-v1/'+config.file,document.baseURI),response=await fetch(url,{cache:'reload'});if(!response.ok)throw Error('地图未下载完整');await cache.put(url,response);if(!await cache.match(url))throw Error('保存尚未完成');if(el.isConnected&&atlasConfig===config)el.textContent='当前区域插画已保存；路书离线资料请在工具中准备';else atlasCacheStatus();}catch(e){if(el.isConnected&&atlasConfig===config)el.textContent='未完成保存：'+e.message;}finally{if(button.isConnected)button.disabled=false;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-atlas-follow]')){atlasLocked=false;atlasPhase='';refreshAtlasTime();saveMapContext();}const open=e.target.closest('[data-atlas-open]');if(open)selectMapPlace(open.dataset.atlasOpen,false);if(e.target.closest('[data-atlas-save]'))prepareAtlasMap();});

